const int mod = 1e9 + 7;
const int MAX = 2e5 + 5;
const int LG = 29;

int binpow(int x, int n) {
    int ans = 1;
    while(n) {
        if(n & 1) ans = (long long) ans * x % mod;
        n >>= 1;
        x = (long long) x * x % mod;
    }
    return ans;
}

int fact[MAX], inv[MAX];

int C(int n, int k) {
    if(n < k || k < 0) return 0;
    return (long long) fact[n] * inv[k] % mod * inv[n - k] % mod;
}

